attributes.onKeyDown:
{(event) => {
                            const direction = lang === "fa" ? -1 : 1;
                            const offset =
                              event.key === "ArrowRight"
                                ? direction
                                : event.key === "ArrowLeft"
                                  ? -direction
                                  : event.key === "ArrowDown"
                                    ? 7
                                    : event.key === "ArrowUp"
                                      ? -7
                                      : event.key === "Home"
                                        ? -day.getDay()
                                        : event.key === "End"
                                          ? 6 - day.getDay()
                                          : undefined;
                            if (offset !== undefined) {
                              event.preventDefault();
                              focusDate(shiftDate(day, offset));
                            } else if (
                              event.key === "PageUp" ||
                              event.key === "PageDown"
                            ) {
                              event.preventDefault();
                              focusDate(
                                shiftMonth(
                                  day,
                                  event.key === "PageUp" ? -1 : 1,
